// ==========================================
// ⚙️ LUNAS WIRKUNG: RUF DER MUTTER (V13 Ready)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (typeof DSK === "undefined" || !globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }

    if (typeof DSK === "undefined" && !globalThis.DSK) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework konnte nicht geladen werden!");
    }
    const DSK_FW = globalThis.DSK || DSK; 

    // --- 2. AKTEUR PRÜFEN ---
    const targetActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!targetActor) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus, liebes Nurtikind!");
    }

    // --- 3. QS & MATHE ERMITTELN ---
    let qsWert = targetActor.getFlag("world", "letzteGabenQS") || 1;
    if (targetActor.getFlag("world", "letzteGabenQS")) {
        await targetActor.unsetFlag("world", "letzteGabenQS"); 
    }

    if (typeof testData !== "undefined") {
        qsWert = Number(testData?.result?.QL || testData?.qualityStep || qsWert);
    }

    const ahne = "Nurti";
    const basisName = "Ruf der Mutter";
    const symbolPfad = DSK_FW.Symbol(ahne);

    const radiusMeter = qsWert * 100;
    const dauerMinuten = qsWert * 5;

    const nutriToken = canvas.tokens.placeables.find(t => t.actor === targetActor) || canvas.tokens.controlled[0];
    if (!nutriToken) {
        return ui.notifications.warn("Kein aktives Token gefunden.");
    }

    const casterName = targetActor.name;
    const finalEffektName = `${basisName} (${ahne}) - Wirkender: ${casterName}`;
    const abschlussText = "Der Ruf der Mutter verhallt. Die Verbindung ist getrennt.";

    // Wirkungsende registrieren
    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("rufDerMutter", finalEffektName, abschlussText);
    }

    // --- 4. FREUNDE & VERWANDTE AUSLESEN ---
    const freundeItem = targetActor.items.find(i => {
        const iName = (i.name || "").toLowerCase();
        return iName.includes("freunde und verwandte") || iName === "freunde";
    });

    let freundNamen = [];
    if (freundeItem) {
        const rawText = freundeItem.system?.description?.value || freundeItem.system?.value || "";
        const cleanedHtml = rawText.replace(/<\/p>|<\/li>|<br\s*[\/]?>/gi, '\n').replace(/<[^>]*>?/gm, '');
        freundNamen = cleanedHtml
            .split(/[\n,]/)
            .map(n => n.replace(/^[•\-\*\s]+/, '').replace(/[•\-\*\s]+$/, '').trim())
            .filter(n => n.length > 0);
    }

    if (freundNamen.length === 0) {
        return ui.notifications.warn("Keine Namen in der Sonderfertigkeit 'Freunde und Verwandte' auf deinem Charakterbogen gefunden!");
    }

    // --- 5. ZIELE IM RADIUS FINDEN ---
    const radiusPx = (radiusMeter / canvas.scene.grid.distance) * canvas.scene.grid.size;

    let zielFreunde = canvas.tokens.placeables.filter(t => {
        if (t.id === nutriToken.id) return false;
        if (!t.actor) return false;

        if (!DSK_FW.Effekt.CheckTarget(t.actor, "erwachte")) return false;

        const tName = t.name.toLowerCase();
        const istBekannt = freundNamen.some(f => tName.includes(f.toLowerCase()) || f.toLowerCase().includes(tName));
        if (!istBekannt) return false;

        const distPx = Math.hypot(t.center.x - nutriToken.center.x, t.center.y - nutriToken.center.y);
        return distPx <= radiusPx;
    });

    if (zielFreunde.length === 0) {
        return ui.notifications.warn("Es befinden sich keine bekannten Freunde oder Verwandten in Reichweite.");
    }

    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    Object.entries(targetActor.ownership || targetActor.permission || {})
        .filter(([id, lvl]) => lvl === 3 && id !== "default")
        .forEach(([id]) => ownerIds.add(id));
    let whisperTargets = Array.from(ownerIds).filter(id => game.users.get(id));

    // --- 6. AUSFÜHRUNGS-LOGIK & RADAR ---
    const execWirkung = async (ids) => {
        const targetTokens = ids.map(id => canvas.tokens.get(id)).filter(t => t);
        const liste = targetTokens.map(t => t.name);

        const descCaster = `Der Ruf der Mutter hallt durch die Umgebung und verbindet die Erwählten mit <b>${nutriToken.name}</b>.<br><br><b>Wahrgenommene Ziele:</b><br>• ${liste.join("<br>• ")}`;
        const descTarget = `Du vernimmst den mütterlichen Ruf von <b>${casterName}</b>. Deine Richtung und Entfernung werden live übermittelt.`;

        // Alten Effekt beim Caster löschen & neu setzen
        for (let ef of targetActor.effects) {
            if ((ef.name || ef.label) === finalEffektName) await ef.delete();
        }
        await DSK_FW.Effekt.Anwenden({
            name: finalEffektName,
            ahne: ahne,
            beschreibung: descCaster,
            gabeZiel: "erwachte",
            qs: qsWert,
            ziel: targetActor
        });

        // Alte Effekte bei Zielen löschen & neu setzen
        for (const t of targetTokens) {
            if (!t.actor) continue;
            for (let ef of t.actor.effects) {
                if ((ef.name || ef.label) === finalEffektName) await ef.delete();
            }
            await DSK_FW.Effekt.Anwenden({
                name: finalEffektName,
                ahne: ahne,
                beschreibung: descTarget,
                gabeZiel: "erwachte",
                qs: qsWert,
                ziel: t.actor
            });
        }

        // Öffentliche / Geflüsterte Chatkarte
        await ChatMessage.create({
            speaker: { alias: "System" },
            content: `
                <div style="font-family:'Signika',sans-serif;">
                    ${DSK_FW.UI.Header(`${basisName} (${ahne})`, symbolPfad)}
                    <div class="dskbox2" style="margin-top:10px;">
                        <p>${descCaster}</p>
                        <hr>
                        <p style="text-align:center; font-weight:bold;">
                            Wirkungsdauer: ${dauerMinuten} Minuten (QS ${qsWert})
                        </p>
                    </div>
                </div>
            `,
            whisper: whisperTargets
        });

        // Live-Radar für die Ziele starten
        let targetUserIds = new Set();
        game.users.filter(u => u.isGM).forEach(u => targetUserIds.add(u.id));
        targetTokens.forEach(t => {
            if (t.actor) {
                const ownership = t.actor.ownership || t.actor.permission || {};
                Object.entries(ownership).filter(([id, lvl]) => lvl === 3 && id !== "default").forEach(([id]) => targetUserIds.add(id));
            }
        });
        const whisperTargetsForRadar = Array.from(targetUserIds).filter(id => game.users.get(id));

        globalThis.rufDerMutterRadar = globalThis.rufDerMutterRadar || {};
        if (globalThis.rufDerMutterRadar[targetActor.id]?.hookUpdate) {
            Hooks.off("updateToken", globalThis.rufDerMutterRadar[targetActor.id].hookUpdate);
        }
        globalThis.rufDerMutterRadar[targetActor.id] = { letzteMsgId: null };

        async function updateRadar() {
            if (!targetActor.effects.find(e => (e.name || e.label) === finalEffektName)) {
                Hooks.off("updateToken", globalThis.rufDerMutterRadar[targetActor.id]?.hookUpdate);
                return;
            }

            const activeNutriToken = canvas.tokens.get(nutriToken.id);
            if (!activeNutriToken) return;

            const aktiveZiele = targetTokens.filter(t => t.actor?.effects.some(e => (e.name || e.label) === finalEffektName));
            if (aktiveZiele.length === 0) return;

            const zielInfos = aktiveZiele.map(t => {
                const dx = activeNutriToken.center.x - t.center.x;
                const dy = activeNutriToken.center.y - t.center.y;
                const distPx = Math.hypot(dx, dy);
                const distSchritt = Math.round(distPx / canvas.scene.grid.size * canvas.scene.grid.distance);

                let deg = Math.atan2(dy, dx) * (180 / Math.PI);
                if (deg < 0) deg += 360;

                const richtungen = ["Osten", "Nordosten", "Norden", "Nordwesten", "Westen", "Südwesten", "Süden", "Südosten"];
                const richtung = richtungen[Math.round(deg / 45) % 8];

                return `• <b>${t.name}:</b> Du spürst den Ruf ca. <b>${distSchritt} Schritt</b> entfernt im <b>${richtung}</b>.`;
            });

            const radarHtml = `
                <div style="font-family: 'Signika', sans-serif;">
                    ${DSK_FW.UI.Header(`${basisName} (Wahrnehmung)`, symbolPfad)}
                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="margin-bottom: 5px;"><b>Du vernimmst den leisen, mütterlichen Ruf:</b></p>
                        ${zielInfos.join("<br>") || "<i>Der Ruf ist schwach...</i>"}
                    </div>
                </div>`;

            const radarData = globalThis.rufDerMutterRadar[targetActor.id];
            if (!radarData) return;

            const msg = game.messages.get(radarData.letzteMsgId);
            if (msg) {
                await msg.update({ content: radarHtml });
            } else {
                const newMsg = await ChatMessage.create({
                    content: radarHtml, 
                    whisper: whisperTargetsForRadar, 
                    speaker: { alias: "System" }
                });
                radarData.letzteMsgId = newMsg.id;
            }
        }

        globalThis.rufDerMutterRadar[targetActor.id].hookUpdate = Hooks.on("updateToken", () => updateRadar());
        updateRadar();
    };

    // --- 7. ENTSCHEIDUNG: AUTOMATISCH ODER GM-DIALOG ---
    if (zielFreunde.length <= qsWert) {
        const allIds = zielFreunde.map(t => t.id);
        execWirkung(allIds);
    } else {
        const itemListHtml = zielFreunde.map(t => `<li style="margin-bottom: 4px;"><b>${t.name}</b></li>`).join("");

        await ChatMessage.create({
            speaker: { alias: "System" },
            content: `
                ${DSK_FW.UI.Header(`${basisName} (${ahne})`, symbolPfad)}
                ${DSK_FW.UI.Box("dskbox2", `
                    <p style="margin-top: 0;">Es sind <b>${zielFreunde.length}</b> Freunde und Verwandte in Reichweite, aber du darfst maximal <b>${qsWert}</b> auswählen:</p>
                    <ul style="margin-bottom: 10px; padding-left: 20px;">
                        ${itemListHtml}
                    </ul>
                    <p style="font-size: 0.85em; color: #555; margin-bottom: 0;"><i>Hinweis: Teile deine Auswahl dem GM mit, damit dieser sie bestätigt.</i></p>
                `)}
            `,
            whisper: whisperTargets
        });

        if (game.user.isGM) {
            const sortierteTokensHtml = zielFreunde.sort((a, b) => a.name.localeCompare(b.name)).map(t => `
                <div style="margin-bottom: 4px;">
                    <label style="cursor: pointer; display: flex; align-items: center; gap: 6px;">
                        <input type="checkbox" name="auswahl" value="${t.id}" style="cursor: pointer;">
                        <span>${t.name}</span>
                    </label>
                </div>
            `).join("");

            const auswahlHTML = `
                <div style="font-family:'Signika',sans-serif;">
                    ${DSK_FW.UI.Header(`${basisName} (${ahne})`, symbolPfad)}
                    <div class="dskbox2" style="margin-top:10px;">
                        <p>Es sind ${zielFreunde.length} Freunde in Reichweite, aber es dürfen max. <b>${qsWert}</b> gewählt werden.<br>
                        Wähle entsprechend der Angabe des Spielers (${casterName}) aus:</p>
                        <hr>
                        <div style="max-height: 200px; overflow-y: auto; margin-bottom: 10px; padding: 4px; background: rgba(0,0,0,0.03); border-radius: 3px;">
                            ${sortierteTokensHtml}
                        </div>
                    </div>
                </div>
            `;

            new Dialog({
                title: `GM: ${basisName} (${casterName})`,
                content: auswahlHTML,
                buttons: {
                    confirm: {
                        icon: '<i class="fas fa-check"></i>',
                        label: "Bestätigen",
                        callback: async (html) => {
                            const container = html instanceof jQuery ? html[0] : html;
                            const checked = [...container.querySelectorAll("input[name='auswahl']:checked")].map(i => i.value);

                            if (checked.length === 0) return ui.notifications.warn("Nichts ausgewählt!");
                            if (checked.length > qsWert) return ui.notifications.warn(`Du darfst maximal ${qsWert} auswählen.`);

                            execWirkung(checked);
                        }
                    },
                    cancel: {
                        icon: '<i class="fas fa-times"></i>',
                        label: "Abbrechen"
                    }
                },
                default: "confirm",
                render: (html) => {
                    const container = html instanceof jQuery ? html[0] : html;
                    if (container) {
                        const buttons = container.querySelectorAll('.dialog-button');
                        buttons.forEach(btn => {
                            btn.style.background = 'linear-gradient(#76301b,#582617)';
                            btn.style.color = '#f8f6f5';
                            btn.style.border = '1px solid #000';
                            btn.style.fontWeight = 'bold';
                        });
                    }
                }
            }).render(true);
        }
    }
})();
